export * from "./app-error";
export * from "./catalog";
export * from "./result";
export * from "./sanitizer";

import { ErrorCatalog, type ErrorCode } from "./catalog";

export type AppErrorContext = Record<string, unknown>;

/**
 * Catalog-driven application error. Framework-agnostic — a plain `Error`, not
 * tied to tRPC/HTTP. Map it at the transport edge.
 *
 * Security contract: `detail` and `context` are **never** sent to the client
 * (`toClient`). `toLog` carries them, but run it through the PII `sanitize`
 * before writing.
 */
export class AppError extends Error {
  readonly key: ErrorCode;
  readonly displayCode: string;
  readonly status: number;
  readonly retryable: boolean;
  readonly title: string;
  /** Server-only detail. Never returned to clients. */
  readonly detail?: string;
  /** Structured log context. Sanitize before logging. */
  readonly context?: AppErrorContext;

  constructor(key: ErrorCode, detail?: string, context?: AppErrorContext, cause?: unknown) {
    const def = ErrorCatalog[key];
    super(def.title, cause !== undefined ? { cause } : undefined);
    this.name = "AppError";
    this.key = key;
    this.displayCode = def.code;
    this.status = def.status;
    this.retryable = def.retryable;
    this.title = def.title;
    this.detail = detail;
    this.context = context;
  }

  /** Safe payload for clients — no detail or context. */
  toClient(): {
    code: string;
    key: ErrorCode;
    title: string;
    retryable: boolean;
  } {
    return {
      code: this.displayCode,
      key: this.key,
      title: this.title,
      retryable: this.retryable,
    };
  }

  /** Full payload for logs — pass `context` through `sanitize` before writing. */
  toLog(): {
    name: string;
    key: ErrorCode;
    code: string;
    status: number;
    detail?: string;
    context?: AppErrorContext;
    stack?: string;
  } {
    return {
      name: this.name,
      key: this.key,
      code: this.displayCode,
      status: this.status,
      detail: this.detail,
      context: this.context,
      stack: this.stack,
    };
  }

  static badRequest(detail?: string, context?: AppErrorContext) {
    return new AppError("BAD_REQUEST", detail, context);
  }
  static unauthorized(detail?: string, context?: AppErrorContext) {
    return new AppError("UNAUTHORIZED", detail, context);
  }
  static forbidden(detail?: string, context?: AppErrorContext) {
    return new AppError("FORBIDDEN", detail, context);
  }
  static notFound(detail?: string, context?: AppErrorContext) {
    return new AppError("NOT_FOUND", detail, context);
  }
  static conflict(detail?: string, context?: AppErrorContext) {
    return new AppError("CONFLICT", detail, context);
  }
  static validation(detail?: string, context?: AppErrorContext) {
    return new AppError("VALIDATION", detail, context);
  }
  static rateLimited(detail?: string, context?: AppErrorContext) {
    return new AppError("RATE_LIMITED", detail, context);
  }
  static internal(detail?: string, context?: AppErrorContext, cause?: unknown) {
    return new AppError("INTERNAL", detail, context, cause);
  }
  static unavailable(detail?: string, context?: AppErrorContext) {
    return new AppError("UNAVAILABLE", detail, context);
  }
  static timeout(detail?: string, context?: AppErrorContext) {
    return new AppError("TIMEOUT", detail, context);
  }
}

export function isAppError(error: unknown): error is AppError {
  return error instanceof AppError;
}

/** Normalize any thrown value into an AppError. */
export function toAppError(error: unknown): AppError {
  if (isAppError(error)) return error;
  if (error instanceof Error) {
    return new AppError("INTERNAL", error.message, undefined, error);
  }
  return new AppError("INTERNAL", String(error));
}

export interface ErrorDef {
  /** Opaque display code, safe to show users/support. */
  readonly code: string;
  /** HTTP-style status for transport mapping. */
  readonly status: number;
  /** Whether retrying the operation may help. */
  readonly retryable: boolean;
  /** Safe, user-facing title. */
  readonly title: string;
}

/** Catalog of generic error codes. Extend per app as needed. */
export const ErrorCatalog = {
  BAD_REQUEST: { code: "E-400", status: 400, retryable: false, title: "Invalid request" },
  UNAUTHORIZED: { code: "E-401", status: 401, retryable: false, title: "Authentication required" },
  FORBIDDEN: {
    code: "E-403",
    status: 403,
    retryable: false,
    title: "You don't have access to this",
  },
  NOT_FOUND: { code: "E-404", status: 404, retryable: false, title: "Not found" },
  CONFLICT: { code: "E-409", status: 409, retryable: false, title: "Conflict" },
  VALIDATION: { code: "E-422", status: 422, retryable: false, title: "Validation failed" },
  RATE_LIMITED: { code: "E-429", status: 429, retryable: true, title: "Too many requests" },
  INTERNAL: { code: "E-500", status: 500, retryable: true, title: "Something went wrong" },
  UNAVAILABLE: { code: "E-503", status: 503, retryable: true, title: "Service unavailable" },
  TIMEOUT: { code: "E-504", status: 504, retryable: true, title: "Request timed out" },
} as const satisfies Record<string, ErrorDef>;

export type ErrorCode = keyof typeof ErrorCatalog;

import { AppError, toAppError } from "./app-error";

export type Ok<T> = { readonly ok: true; readonly value: T };
export type Err<E> = { readonly ok: false; readonly error: E };
export type Result<T, E = AppError> = Ok<T> | Err<E>;

export const ok = <T>(value: T): Ok<T> => ({ ok: true, value });
export const err = <E>(error: E): Err<E> => ({ ok: false, error });

/** Run `fn`, returning a `Result` instead of throwing. Errors become `AppError`. */
export async function tryCatch<T>(fn: () => Promise<T> | T): Promise<Result<T, AppError>> {
  try {
    return ok(await fn());
  } catch (caught) {
    return err(toAppError(caught));
  }
}

export class TimeoutError extends Error {
  readonly ms: number;
  constructor(ms: number) {
    super(`Operation timed out after ${ms}ms`);
    this.name = "TimeoutError";
    this.ms = ms;
  }
}

/** Reject with `TimeoutError` if `promise` doesn't settle within `ms`. */
export function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new TimeoutError(ms)), ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

export interface RetryOptions {
  /** Total attempts including the first (default 3). */
  attempts?: number;
  /** Base delay in ms (default 500). */
  baseDelay?: number;
  /** Jitter fraction 0..1 (default 0.2). */
  jitter?: number;
  /** Decide if an error is retryable (default: `error.retryable`). */
  retryable?: (error: AppError) => boolean;
  onRetry?: (attempt: number, error: AppError) => void;
  /** Injectable for tests. */
  sleep?: (ms: number) => Promise<void>;
  /** Injectable for tests. */
  random?: () => number;
}

/** Retry `fn` with exponential backoff while the error is retryable. */
export async function retry<T>(
  fn: () => Promise<T> | T,
  options: RetryOptions = {},
): Promise<Result<T, AppError>> {
  const attempts = options.attempts ?? 3;
  const baseDelay = options.baseDelay ?? 500;
  const jitter = options.jitter ?? 0.2;
  const isRetryable = options.retryable ?? ((error) => error.retryable);
  const sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
  const random = options.random ?? Math.random;

  let last: AppError | undefined;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const result = await tryCatch(fn);
    if (result.ok) return result;

    last = result.error;
    if (attempt === attempts || !isRetryable(result.error)) break;

    options.onRetry?.(attempt, result.error);
    const delay = baseDelay * 2 ** (attempt - 1);
    const jitterMs = delay * jitter * (random() * 2 - 1);
    await sleep(Math.max(0, delay + jitterMs));
  }

  return err(last ?? new AppError("INTERNAL", "retry exhausted"));
}

/**
 * PII sanitization — the last line of defense before values reach a log
 * transport. Masks the values of sensitive keys and obvious secrets/PII in
 * free strings. Add keys as new sensitive fields appear.
 */
const SENSITIVE_KEYS = new Set([
  // auth credentials
  "password",
  "newpassword",
  "currentpassword",
  "confirmpassword",
  "passwordhash",
  "secret",
  "token",
  "accesstoken",
  "refreshtoken",
  "idtoken",
  "sessiontoken",
  "authtoken",
  "bearertoken",
  "csrftoken",
  // api / crypto keys
  "apikey",
  "apisecret",
  "privatekey",
  "encryptionkey",
  "signingkey",
  "webhooksecret",
  "cronsecret",
  "internalsecret",
  "hmac",
  "signature",
  "salt",
  "nonce",
  "iv",
  // financial pii
  "creditcard",
  "cardnumber",
  "cvv",
  "cvc",
  "iban",
  "pan",
  "taxid",
  // personal pii / transport
  "email",
  "phone",
  "ssn",
  "authorization",
  "cookie",
  "setcookie",
]);

export const REDACTED = "[REDACTED]";

const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
const BEARER_RE = /\bBearer\s+[A-Za-z0-9._-]+/gi;

/** Normalize a key for lookup: `API_KEY`, `apiKey`, `api-key` → `apikey`. */
function normalizeKey(key: string): string {
  return key.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function maskString(value: string): string {
  return value.replace(EMAIL_RE, REDACTED).replace(BEARER_RE, `Bearer ${REDACTED}`);
}

/** Recursively mask sensitive keys and secrets/PII in strings. Circular-safe. */
export function sanitize(input: unknown, seen = new WeakSet<object>()): unknown {
  if (typeof input === "string") return maskString(input);
  if (input === null || typeof input !== "object") return input;
  if (seen.has(input)) return "[Circular]";
  seen.add(input);

  if (Array.isArray(input)) return input.map((value) => sanitize(value, seen));

  const output: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(input)) {
    output[key] = SENSITIVE_KEYS.has(normalizeKey(key)) ? REDACTED : sanitize(value, seen);
  }
  return output;
}
